        "sinopse": "Wan é um estudante universitário que tem como hobby ser fã e acompanhar de perto o astro em ascensão Nine, seguindo-o e tirando fotos dele. Quando Wan consegue uma oportunidade para atuar em um papel secundário em uma série BL na qual seu ídolo será um dos protagonistas, ele conhece Third, um dos protagonistas e parceiro de ship de Nine, conhecido por sua língua afiada.\n\nOs dois entram em conflito imediatamente, mas, depois que Wan passa na audição, são obrigados a trabalhar juntos. Apesar da antipatia inicial, conforme começa a conhecer melhor Third, Wan passa a enxergar seu rival de uma maneira diferente. Ele não entende o que está acontecendo consigo mesmo, mas percebe que está evitando cada vez mais o olhar daquele protagonista convencido.\n\nAlém disso, Wan começa a descobrir que, por trás das câmeras, a indústria que parecia tão brilhante não é exatamente como ele imaginava. Até mesmo Nine, seu próprio ídolo, está escondendo algo bastante suspeito.",
